const now = new Date();
const day = now.getDate();
const isMonthly = day === 1;

let startDate, endDate;
if (isMonthly) {
  const y = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const m = now.getMonth() === 0 ? 11 : now.getMonth() - 1;
  startDate = new Date(y, m, 1);
  endDate = new Date(y, m + 1, 0);
} else {
  endDate = new Date(now);
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 7);
}

const fmt = d => d.toISOString().split('T')[0];

return [{ json: {
  period: isMonthly ? 'Mensal' : 'Semanal',
  start_date: fmt(startDate),
  end_date: fmt(endDate)
}}];

const raw = $input.first().json;
if (raw.error) throw new Error(`Facebook API error: ${raw.error.message}`);
const campaigns = raw.data || [];

const leadTypes = [
  'lead',
  'onsite_conversion.lead_grouped',
  'offsite_conversion.fb_pixel_lead',
  'contact',
];

return campaigns
  .map(c => {
    const actions = c.actions || [];
    const leads = leadTypes.reduce((sum, t) => {
      const a = actions.find(x => x.action_type === t);
      return sum + (a ? parseFloat(a.value) : 0);
    }, 0);
    const spend = parseFloat(c.spend || 0);
    return { json: {
      source: 'Facebook Ads',
      campaign: c.campaign_name || 'Unknown',
      spend,
      leads: Math.round(leads),
      cpl: leads > 0 ? parseFloat((spend / leads).toFixed(2)) : null,
    }};
  })
  .filter(i => i.json.spend > 0);

const raw = $input.first().json;
if (raw.error) throw new Error(`Google Ads API error: ${JSON.stringify(raw.error)}`);
const results = raw.results || [];

return results
  .map(r => {
    const spend = (r.metrics?.costMicros || 0) / 1_000_000;
    const leads = r.metrics?.conversions || 0;
    return { json: {
      source: 'Google Ads',
      campaign: r.campaign?.name || 'Unknown',
      spend: parseFloat(spend.toFixed(2)),
      leads: Math.round(leads),
      cpl: leads > 0 ? parseFloat((spend / leads).toFixed(2)) : null,
    }};
  })
  .filter(i => i.json.spend > 0);

const items = $input.all().map(i => i.json);
const period = $('Set Period').first().json;

const R = n => n != null
  ? 'R$ ' + Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  : '—';

const fb = items.filter(i => i.source === 'Facebook Ads');
const ga = items.filter(i => i.source === 'Google Ads');
const sumOf = (arr, k) => arr.reduce((s, i) => s + Number(i[k] || 0), 0);

const totalFbSpend = sumOf(fb, 'spend');
const totalFbLeads = sumOf(fb, 'leads');
const totalGSpend  = sumOf(ga, 'spend');
const totalGLeads  = sumOf(ga, 'leads');
const totalSpend   = totalFbSpend + totalGSpend;
const totalLeads   = totalFbLeads + totalGLeads;

const campFields = arr => arr.slice(0, 10).map(c => ({
  name: c.campaign.slice(0, 256),
  value: `Leads: **${c.leads}** | Gasto: **${R(c.spend)}** | CPL: **${R(c.cpl)}**`,
  inline: true,
}));

const fields = [];
if (fb.length) {
  fields.push({
    name: '📘 Facebook Ads',
    value: `Gasto: **${R(totalFbSpend)}** | Leads: **${totalFbLeads}** | CPL: **${totalFbLeads > 0 ? R(totalFbSpend / totalFbLeads) : '—'}**`,
    inline: false,
  });
  fields.push(...campFields(fb));
}
if (ga.length) {
  fields.push({
    name: '🟢 Google Ads',
    value: `Gasto: **${R(totalGSpend)}** | Leads: **${totalGLeads}** | CPL: **${totalGLeads > 0 ? R(totalGSpend / totalGLeads) : '—'}**`,
    inline: false,
  });
  fields.push(...campFields(ga));
}

const payload = {
  embeds: [{
    title: `📣 Mídia Paga — ${period.period}`,
    description: [
      `📅 Período: **${period.start_date}** até **${period.end_date}**`,
      ``,
      `💰 Investimento Total: **${R(totalSpend)}**`,
      `🎯 Leads Totais: **${totalLeads}**`,
      `📉 CPL Médio: **${totalLeads > 0 ? R(totalSpend / totalLeads) : '—'}**`,
    ].join('\n'),
    color: 0xEB4034,
    fields: fields.slice(0, 25),
    footer: {
      text: `Gerado em ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`,
    },
  }],
};

return [{ json: { payload } }];
